```go
package lru

type node struct {
	key, val   int
	prev, next *node
}

type LRUCache struct {
	capacity   int
	items      map[int]*node
	head, tail *node // head = most recently used
}

func Constructor(capacity int) LRUCache {
	head, tail := &node{}, &node{}
	head.next = tail
	tail.prev = head
	return LRUCache{
		capacity: capacity,
		items:    make(map[int]*node, capacity),
		head:     head,
		tail:     tail,
	}
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.items[key]
	if !ok {
		return -1
	}
	c.moveToFront(n)
	return n.val
}

func (c *LRUCache) Put(key int, value int) {
	if n, ok := c.items[key]; ok {
		n.val = value
		c.moveToFront(n)
		return
	}
	n := &node{key: key, val: value}
	c.items[key] = n
	c.pushFront(n)
	if len(c.items) > c.capacity {
		lru := c.tail.prev
		c.remove(lru)
		delete(c.items, lru.key)
	}
}

func (c *LRUCache) pushFront(n *node) {
	n.prev = c.head
	n.next = c.head.next
	c.head.next.prev = n
	c.head.next = n
}

func (c *LRUCache) remove(n *node) {
	n.prev.next = n.next
	n.next.prev = n.prev
}

func (c *LRUCache) moveToFront(n *node) {
	c.remove(n)
	c.pushFront(n)
}
```

I hand-rolled a doubly linked list with sentinel head and tail nodes, so every insert and removal is a constant number of pointer swaps, and the map gives O(1) lookup by key. Get moves the node to the front, Put updates in place or evicts the tail's previous node when over capacity. Time is O(1) for both get and put, space is O(capacity).

## Approach
Treat the grid as a graph where each land cell `'1'` is a node and its four orthogonal neighbors are edges. Scan every cell, and each time I hit unvisited land, I run a BFS from it to flood the whole island, marking cells as `'0'` so they're never counted again. Each cell is enqueued at most once, so the total work is linear in the grid size.

## Code
```go
func numIslands(grid [][]byte) int {
	if len(grid) == 0 || len(grid[0]) == 0 {
		return 0
	}
	rows, cols := len(grid), len(grid[0])
	count := 0
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if grid[r][c] != '1' {
				continue
			}
			count++
			grid[r][c] = '0'
			queue := [][2]int{{r, c}}
			for len(queue) > 0 {
				cur := queue[0]
				queue = queue[1:]
				for _, d := range dirs {
					nr, nc := cur[0]+d[0], cur[1]+d[1]
					if nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != '1' {
						continue
					}
					grid[nr][nc] = '0'
					queue = append(queue, [2]int{nr, nc})
				}
			}
		}
	}
	return count
}
```

## Complexity
Time is **O(rows × cols)**, since every cell is visited a constant number of times. Space is **O(rows × cols)** in the worst case for the queue, when the whole grid is one island.

```python
def first_unique_char(s: str) -> str:
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in s:
        if counts[ch] == 1:
            return ch
    return ""
```

Two passes: the first builds a frequency map, the second returns the first character whose count is 1, or an empty string if every character repeats. Time is O(n) and space is O(k), where k is the number of distinct characters.

